// Render carousel slides 2..n (generated by the calendar template) at 1080 x 1350.
// Usage: node render_slides.js <outDir>    (reads ../xzone-summer-calendar.html; run build.py first)
const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const OUT = process.argv[2];
  const b = await chromium.launch();
  const pg = await b.newPage({ viewport: { width: 1200, height: 1500 } });
  pg.on('pageerror', e => console.log('ERR', e.message));
  await pg.goto('file://' + path.resolve(__dirname, '..', 'xzone-summer-calendar.html'));
  await pg.waitForTimeout(800);
  await pg.evaluate(() => document.fonts.ready);
  // every generated slide; hand-built slides (DES "<id>:<n>") are skipped
  const jobs = await pg.evaluate(() => {
    const out = [];
    all.forEach(p => {
      if (p.template !== 'carousel') return;
      const n = (p.slides || []).length;
      for (let i = 1; i < n; i++) if (!DES[p.id + ':' + (i + 1)]) out.push([p.id, i, n]);
    });
    return out;
  });
  await pg.addStyleTag({ content: '#stage{position:fixed;left:0;top:0;width:1080px;z-index:99999}#stage .pv{width:1080px}body{overflow:hidden}' });
  for (const [id, i, n] of jobs) {
    await pg.evaluate(([id, i, n]) => {
      let st = document.getElementById('stage');
      if (!st) { st = document.createElement('div'); st.id = 'stage'; document.body.appendChild(st); }
      const p = all.find(x => x.id === id);
      st.innerHTML = slide(p, p.slides[i], i, n);
    }, [id, i, n]);
    await pg.waitForTimeout(60);
    const el = await pg.$('#stage .pv');
    await el.screenshot({ path: `${OUT}/${id}-slide-${String(i + 1).padStart(2, '0')}.png` });
  }
  console.log('slides', jobs.length);
  await b.close();
})();
